        if(stage==20){if(!reloadMeasured)return false;originalIntact(world);GearTileEntity raised=ArmCoreGapRaisedFixture.build(world,actor);ROOT=ArmCoreGapRaisedFixture.ROOT;location(actor,raised);ArmTransactions.testFault=point->{if("prepared".equals(point)){need(world.getMinecraftServer().isCallingFromMinecraftThread(),"real journal callback remains on server thread");prepared++;}};stage=30;ticks=0;sent=false;System.out.println("[vandorlabs][reprolab] saved-core-gap variant RAISED separateOrdinaryConstruction root="+ROOT+" floorLowerBy7 h5/twoColumns/ROTATE/Double/South");return false;}
