    private static void measure(GearTileEntity arm)throws Exception{ArmCoreGapRenderChecks.Sample sample=ArmCoreGapRenderChecks.emit(arm);ArmPayload p=arm.payload();Vec3d origin=p.transform(arm,sample.phase,0,0,0),normal=p.transform(arm,sample.phase,0,1,0).subtract(origin);double core=Double.POSITIVE_INFINITY,raw=core,socket=Double.NEGATIVE_INFINITY;GearMotion.Pose pose=arm.pose(sample.phase);for(int i=0;i<sample.core.length;i+=3){double x=sample.core[i],y=sample.core[i+1],z=sample.core[i+2];core=Math.min(core,p.transform(arm,sample.phase,x,y,z).dotProduct(normal));raw=Math.min(raw,p.rawTransform(arm,pose,x,y,z).dotProduct(normal));}for(int i=0;i<sample.sockets.length;i+=3)socket=Math.max(socket,new Vec3d(sample.sockets[i],sample.sockets[i+1],sample.sockets[i+2]).dotProduct(normal));double separation=core-socket,authored=raw-socket;System.out.println("[vandorlabs][reprolab] saved-core-gap emitted phase="+sample.phase+" gap="+separation+" rawContact="+authored+" coreVertices="+sample.core.length/3+" socketVertices="+sample.sockets.length/3);need(Math.abs(separation-authored)<.0002,"actual Core/socket endpoint snapping introduces gap="+separation+" authored="+authored);need(Math.abs(authored-1/16D)<.0002,"actual authored one-pixel Core/socket clearance retained");samples++;}
